package com.ttcs.meetingmanagement;

import jakarta.persistence.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.time.format.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import com.fasterxml.jackson.annotation.JsonAutoDetect; import tools.jackson.databind.*;
@SpringBootApplication public class MeetingManagementApplication {public static void main(String[] a){SpringApplication.run(MeetingManagementApplication.class,a);}}
enum MeetingStatus{SCHEDULED,CONFIRMED,CANCELLED,COMPLETED}
enum ParticipantStatus{INVITED,ACCEPTED,DECLINED,REMOVED}
@JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY)
@Entity @Table(name="rooms") class Room{@Id @Column(name="room_id") String id;@Column(name="room_name",nullable=false,unique=true)String name;int capacity;String location;@Column(name="qr_code")String qrCode;@Column(nullable=false)String status="AVAILABLE";protected Room(){}Room(String i,String n,int c,String l){id=i;name=n;capacity=c;location=l;}}
@Entity @Table(name="meetings") class Meeting{@Id @Column(name="meeting_id",length=36)String id;@Column(name="organizer_id",nullable=false)String organizerId;@Column(name="room_id",nullable=false)String roomId;@Column(nullable=false)String title;@Column(columnDefinition="TEXT")String description;@Column(name="start_time",nullable=false)OffsetDateTime startTime;@Column(name="end_time",nullable=false)OffsetDateTime endTime;@Enumerated(EnumType.STRING)@Column(nullable=false)MeetingStatus status=MeetingStatus.SCHEDULED;@Column(name="is_recurring",nullable=false)boolean recurring=false;@Column(name="recurrence_rule")String recurrenceRule;@Column(name="recurrence_series_id",length=36)String recurrenceSeriesId;@Column(name="cancel_reason")String cancelReason;@Column(name="cancelled_at")OffsetDateTime cancelledAt;@Column(name="created_at",nullable=false)OffsetDateTime createdAt;@Column(name="updated_at",nullable=false)OffsetDateTime updatedAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID().toString();createdAt=updatedAt=OffsetDateTime.now();}@PreUpdate void update(){updatedAt=OffsetDateTime.now();}}
@Entity @Table(name="users") class UserDirectoryEntry{@Id @Column(name="user_id",length=36)String id;@Column(name="full_name")String fullName;String email;String status;}
@Entity @Table(name="meeting_participants",uniqueConstraints=@UniqueConstraint(columnNames={"meeting_id","user_id"})) class MeetingParticipant{@Id @Column(name="participant_id",length=36)String id;@Column(name="meeting_id",nullable=false,length=36)String meetingId;@Column(name="user_id",nullable=false,length=36)String userId;@Column(name="full_name")String fullName;String email;@Column(name="account_active",nullable=false)boolean accountActive=true;@Enumerated(EnumType.STRING)@Column(nullable=false)ParticipantStatus status=ParticipantStatus.INVITED;@Column(name="responded_at")OffsetDateTime respondedAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID().toString();}}
interface RoomRepository extends JpaRepository<Room,String>{@Lock(LockModeType.PESSIMISTIC_WRITE)List<Room> findByStatusAndCapacityGreaterThanEqualOrderByCapacity(String status,int capacity);@Lock(LockModeType.PESSIMISTIC_WRITE)Optional<Room> findLockedById(String id);}
interface MeetingRepository extends JpaRepository<Meeting,String>{long countByRoomIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(String room,Collection<MeetingStatus> statuses,OffsetDateTime end,OffsetDateTime start);}
interface UserDirectoryRepository extends JpaRepository<UserDirectoryEntry,String>{}
interface ParticipantRepository extends JpaRepository<MeetingParticipant,String>{}
record ChatBookingRequest(@NotBlank String organizerId,@NotBlank String title,String description,@NotNull OffsetDateTime startTime,@NotNull OffsetDateTime endTime,@Min(1)int attendees,String roomId,List<String> participantIds,Boolean recurring,String recurrenceRule){ChatBookingRequest(String organizerId,String title,OffsetDateTime startTime,OffsetDateTime endTime,int attendees,String roomId){this(organizerId,title,null,startTime,endTime,attendees,roomId,List.of(),false,null);}}
record ChatBookingResponse(String message,String meetingId,String roomId,String roomName,OffsetDateTime startTime,OffsetDateTime endTime){}
record AvailableRoom(String id,String name,int capacity,String location) {static AvailableRoom of(Room r){return new AvailableRoom(r.id,r.name,r.capacity,r.location);}}
record ChatMessageRequest(String sessionId,@NotBlank String message){}
record ChatMessageResponse(String sessionId,String reply,String step,ChatBookingResponse booking,List<AvailableRoom> roomOptions){}
@Service class ChatbotBookingService{final RoomRepository rooms;final MeetingRepository meetings;final UserDirectoryRepository users;final ParticipantRepository participants;ChatbotBookingService(RoomRepository r,MeetingRepository m,UserDirectoryRepository u,ParticipantRepository p){rooms=r;meetings=m;users=u;participants=p;}List<AvailableRoom> availableRooms(OffsetDateTime start,OffsetDateTime end,int attendees){if(start==null||end==null||!end.isAfter(start)||attendees<1)return List.of();return rooms.findAll().stream().filter(r->"AVAILABLE".equals(r.status)&&r.capacity>=attendees).filter(r->meetings.countByRoomIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(r.id,List.of(MeetingStatus.SCHEDULED,MeetingStatus.CONFIRMED),end,start)==0).sorted(Comparator.comparingInt(r->r.capacity)).map(AvailableRoom::of).toList();}@Transactional ChatBookingResponse book(ChatBookingRequest q){if(!q.endTime().isAfter(q.startTime()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Thời gian kết thúc phải sau thời gian bắt đầu");if(!q.startTime().isAfter(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Chỉ đặt được thời gian trong tương lai");UserDirectoryEntry organizer=users.findById(q.organizerId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Người tổ chức không tồn tại hoặc chưa được đồng bộ"));if(!"ACTIVE".equalsIgnoreCase(organizer.status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Người tổ chức đã bị vô hiệu hóa");List<Room> candidates=q.roomId()!=null&&!q.roomId().isBlank()?List.of(rooms.findLockedById(q.roomId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy phòng"))):rooms.findByStatusAndCapacityGreaterThanEqualOrderByCapacity("AVAILABLE",q.attendees());Room chosen=candidates.stream().filter(r->"AVAILABLE".equals(r.status)&&r.capacity>=q.attendees()).filter(r->meetings.countByRoomIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(r.id,List.of(MeetingStatus.SCHEDULED,MeetingStatus.CONFIRMED),q.endTime(),q.startTime())==0).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Phòng vừa được đặt hoặc không còn phòng phù hợp. Hãy tìm lại phòng trống."));Meeting m=new Meeting();m.organizerId=q.organizerId();m.roomId=chosen.id;m.title=q.title().trim();m.description=q.description();m.startTime=q.startTime();m.endTime=q.endTime();m.recurring=Boolean.TRUE.equals(q.recurring());m.recurrenceRule=q.recurrenceRule();meetings.saveAndFlush(m);for(String userId:Optional.ofNullable(q.participantIds()).orElse(List.of())){UserDirectoryEntry u=users.findById(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Người tham dự không tồn tại: "+userId));if(!"ACTIVE".equalsIgnoreCase(u.status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Người tham dự đã bị vô hiệu hóa: "+userId);MeetingParticipant p=new MeetingParticipant();p.meetingId=m.id;p.userId=u.id;p.fullName=u.fullName;p.email=u.email;participants.save(p);}return new ChatBookingResponse("Đã đặt "+chosen.name+" thành công",m.id,chosen.id,chosen.name,m.startTime,m.endTime);}}

record AiBookingDraft(String organizerId,String title,String startTime,String endTime,Integer attendees,String roomId,List<String> participantIds,String reply){}
@Service class GeminiIntentService{
  private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(GeminiIntentService.class);
  private final RestClient http;private final ObjectMapper json;private final String apiKey,model;
  GeminiIntentService(ObjectMapper json,@Value("${gemini.api-key:}")String apiKey,@Value("${gemini.model:gemini-2.5-flash}")String model,@Value("${gemini.base-url:https://generativelanguage.googleapis.com/v1beta}")String baseUrl){this.http=RestClient.builder().baseUrl(baseUrl).build();this.json=json;this.apiKey=apiKey;this.model=model;}
  boolean enabled(){return apiKey!=null&&!apiKey.isBlank();}
  Optional<AiBookingDraft> analyze(String message){if(!enabled())return Optional.empty();try{Map<String,Object> nullableString=Map.of("type",List.of("string","null"));Map<String,Object> nullableInteger=Map.of("type",List.of("integer","null"));Map<String,Object> schema=Map.of("type","object","properties",Map.of("organizerId",nullableString,"title",nullableString,"startTime",nullableString,"endTime",nullableString,"attendees",nullableInteger,"roomId",nullableString,"participantIds",Map.of("type","array","items",Map.of("type","string")),"reply",Map.of("type","string")),"required",List.of("organizerId","title","startTime","endTime","attendees","roomId","participantIds","reply"));String instruction="Bạn trích xuất yêu cầu đặt phòng họp bằng tiếng Việt. Hôm nay là "+LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh"))+". Múi giờ +07:00. Chuyển thời gian sang ISO 8601 có offset. Trường thiếu trả null, participantIds thiếu trả mảng rỗng. roomId là mã kiểu ROOM-A; nếu người dùng muốn hệ thống tự chọn thì null. reply là câu tiếng Việt ngắn giải thích thông tin đã hiểu hoặc cần bổ sung. Không tự bịa ID người dùng. Yêu cầu của người dùng: "+message;Map<String,Object> body=Map.of("contents",List.of(Map.of("role","user","parts",List.of(Map.of("text",instruction)))),"generationConfig",Map.of("response_mime_type","application/json","response_schema",schema));JsonNode response=http.post().uri("/models/{model}:generateContent",model).header("x-goog-api-key",apiKey).body(body).retrieve().body(JsonNode.class);String output=response==null?null:response.path("candidates").path(0).path("content").path("parts").path(0).path("text").asText(null);return output==null?Optional.empty():Optional.of(json.readValue(output,AiBookingDraft.class));}catch(Exception ex){log.warn("Không thể gọi Gemini model {}: {}",model,ex.getMessage());return Optional.empty();}}
}

@Service class ChatConversationService{
  enum Step{ORGANIZER,TITLE,START,END,ATTENDEES,PARTICIPANTS,ROOM,CONFIRM,DONE}
  static class State{Step step=Step.ORGANIZER;String organizerId,title;OffsetDateTime start,end;int attendees;List<String> participantIds=List.of();String roomId;List<AvailableRoom> roomOptions=List.of();}
  private final Map<String,State> sessions=new ConcurrentHashMap<>();private final UserDirectoryRepository users;private final RoomRepository rooms;private final ChatbotBookingService booking;private final GeminiIntentService ai;
  ChatConversationService(UserDirectoryRepository u,RoomRepository r,ChatbotBookingService b,GeminiIntentService ai){users=u;rooms=r;booking=b;this.ai=ai;}
  ChatMessageResponse reply(ChatMessageRequest request){String id=request.sessionId()==null||request.sessionId().isBlank()?UUID.randomUUID().toString():request.sessionId();String text=request.message().trim();if(isReset(text)){sessions.put(id,new State());return answer(id,"Đã bắt đầu lại. Bạn có thể mô tả toàn bộ yêu cầu hoặc nhập mã người tổ chức.",Step.ORGANIZER,null);}State state=sessions.computeIfAbsent(id,k->new State());try{if(state.step==Step.ORGANIZER&&looksNatural(text)){Optional<AiBookingDraft> draft=ai.analyze(text).or(()->localDraft(text));if(draft.isPresent())return applyDraft(id,state,draft.get());}return advance(id,state,text);}catch(ResponseStatusException ex){return answer(id,Objects.toString(ex.getReason(),"Không thể xử lý yêu cầu."),state.step,null);}catch(RuntimeException ex){return answer(id,ex.getMessage(),state.step,null);}}
  private static Optional<AiBookingDraft> localDraft(String text){
    String normalized=text.trim();String organizer=firstMatch(normalized,"(?i)\\b(user-[a-z0-9_-]+)\\b");Integer attendees=integerMatch(normalized,"(?i)(\\d+)\\s*người");
    String title=firstMatch(normalized,"(?i)đặt\\s+phòng(?:\\s+họp)?\\s+(.+?)\\s+cho\\s+\\d+\\s*người");
    List<String> ids=new ArrayList<>();var idMatcher=java.util.regex.Pattern.compile("(?i)\\buser-[a-z0-9_-]+\\b").matcher(normalized);while(idMatcher.find()){String value=idMatcher.group().toLowerCase(Locale.ROOT);if(!value.equalsIgnoreCase(organizer)&&!ids.contains(value))ids.add(value);}
    LocalDate date=null;String dateText=firstMatch(normalized,"\\b(\\d{1,2}/\\d{1,2}/\\d{4})\\b");ZoneId zone=ZoneId.of("Asia/Ho_Chi_Minh");
    if(dateText!=null)try{date=LocalDate.parse(dateText,DateTimeFormatter.ofPattern("d/M/yyyy"));}catch(DateTimeParseException ignored){}else if(normalized.toLowerCase(Locale.ROOT).contains("ngày mai"))date=LocalDate.now(zone).plusDays(1);
    var times=new ArrayList<LocalTime>();var timeMatcher=java.util.regex.Pattern.compile("(?<!\\d)([01]?\\d|2[0-3])[:h]([0-5]\\d)(?!\\d)",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(normalized);while(timeMatcher.find())times.add(LocalTime.of(Integer.parseInt(timeMatcher.group(1)),Integer.parseInt(timeMatcher.group(2))));
    OffsetDateTime start=date!=null&&!times.isEmpty()?date.atTime(times.get(0)).atZone(zone).toOffsetDateTime():null;OffsetDateTime end=date!=null&&times.size()>1?date.atTime(times.get(1)).atZone(zone).toOffsetDateTime():null;
    if(start!=null&&end==null){Integer hours=integerMatch(normalized,"(?i)trong\\s+(\\d+)\\s*(?:tiếng|giờ)");if(hours!=null)end=start.plusHours(hours);}
    String room=firstMatch(normalized,"(?i)\\b(ROOM-[A-Z0-9_-]+)\\b");if(organizer==null&&attendees==null&&start==null)return Optional.empty();
    return Optional.of(new AiBookingDraft(organizer,title,start==null?null:start.toString(),end==null?null:end.toString(),attendees,room,ids,"Mình đã đọc yêu cầu và sẽ hỏi thêm những thông tin còn thiếu."));
  }
  private static String firstMatch(String text,String regex){var matcher=java.util.regex.Pattern.compile(regex,java.util.regex.Pattern.CASE_INSENSITIVE|java.util.regex.Pattern.UNICODE_CASE).matcher(text);return matcher.find()?matcher.group(1).trim():null;}
  private static Integer integerMatch(String text,String regex){String value=firstMatch(text,regex);return value==null?null:Integer.valueOf(value);}
  private ChatMessageResponse applyDraft(String id,State s,AiBookingDraft d){if(d.organizerId()!=null){UserDirectoryEntry u=users.findById(d.organizerId()).orElseThrow(()->bad("AI nhận được mã người tổ chức '"+d.organizerId()+"' nhưng người này không tồn tại."));if(!"ACTIVE".equalsIgnoreCase(u.status))throw bad("Người tổ chức đã bị vô hiệu hóa.");s.organizerId=u.id;}s.title=blankToNull(d.title());if(d.startTime()!=null)s.start=OffsetDateTime.parse(d.startTime());if(d.endTime()!=null)s.end=OffsetDateTime.parse(d.endTime());if(d.attendees()!=null)s.attendees=d.attendees();s.participantIds=d.participantIds()==null?List.of():d.participantIds();validateDraft(s);s.step=nextMissing(s);String prefix=d.reply()==null||d.reply().isBlank()?"":d.reply()+"\n";if(s.step!=Step.CONFIRM)return answer(id,prefix+promptFor(s),s.step,null);ChatMessageResponse choices=showAvailableRooms(id,s,prefix+"Mình đã truy vấn lịch trong cơ sở dữ liệu.");String requested=blankToNull(d.roomId());if(requested==null||s.roomOptions.stream().noneMatch(r->r.id().equalsIgnoreCase(requested)))return choices;s.roomId=requested.toUpperCase(Locale.ROOT);s.step=Step.CONFIRM;return answer(id,prefix+summary(s)+"\nNhập 'xác nhận' để đặt phòng hoặc 'làm lại' để bắt đầu lại.",s.step,null);}
  private static Step nextMissing(State s){if(s.organizerId==null)return Step.ORGANIZER;if(s.title==null)return Step.TITLE;if(s.start==null)return Step.START;if(s.end==null)return Step.END;if(s.attendees<1)return Step.ATTENDEES;return Step.CONFIRM;}
  private String promptFor(State s){return switch(s.step){case ORGANIZER->"Hãy nhập mã người tổ chức.";case TITLE->"Cuộc họp có tiêu đề gì?";case START->"Cuộc họp bắt đầu lúc nào?";case END->"Cuộc họp kết thúc lúc nào?";case ATTENDEES->"Có bao nhiêu người tham dự?";default->"Hãy tiếp tục.";};}
  private ChatMessageResponse advance(String id,State s,String text){switch(s.step){
    case ORGANIZER->{UserDirectoryEntry u=users.findById(text).orElseThrow(()->bad("Không tìm thấy người dùng '"+text+"'. Hãy nhập lại mã người tổ chức."));if(!"ACTIVE".equalsIgnoreCase(u.status))throw bad("Tài khoản này đang bị vô hiệu hóa. Hãy chọn người tổ chức khác.");s.organizerId=u.id;s.step=Step.TITLE;return answer(id,"Xin chào "+Objects.toString(u.fullName,u.id)+". Cuộc họp có tiêu đề gì?",s.step,null);}
    case TITLE->{s.title=text;s.step=Step.START;return answer(id,"Cuộc họp bắt đầu lúc nào? Nhập theo dạng dd/MM/yyyy HH:mm, ví dụ 12/10/2026 14:00.",s.step,null);}
    case START->{s.start=parseTime(text);if(!s.start.isAfter(OffsetDateTime.now()))throw bad("Thời gian bắt đầu phải ở tương lai. Hãy nhập lại.");s.step=Step.END;return answer(id,"Cuộc họp kết thúc lúc nào?",s.step,null);}
    case END->{s.end=parseTime(text);if(!s.end.isAfter(s.start))throw bad("Thời gian kết thúc phải sau thời gian bắt đầu. Hãy nhập lại.");s.step=Step.ATTENDEES;return answer(id,"Có bao nhiêu người tham dự?",s.step,null);}
    case ATTENDEES->{try{s.attendees=Integer.parseInt(text);}catch(NumberFormatException e){throw bad("Số người phải là số nguyên dương.");}if(s.attendees<1)throw bad("Số người phải lớn hơn 0.");s.step=Step.PARTICIPANTS;return answer(id,"Nhập mã người tham dự, cách nhau bằng dấu phẩy; hoặc nhập 'không'.",s.step,null);}
    case PARTICIPANTS->{s.participantIds=isSkip(text)?List.of():Arrays.stream(text.split(",")).map(String::trim).filter(x->!x.isBlank()).toList();validateParticipants(s);return showAvailableRooms(id,s,"Mình đã truy vấn lịch trong cơ sở dữ liệu.");}
    case ROOM->{if(s.roomOptions.isEmpty())return showAvailableRooms(id,s,"Danh sách phòng đã được làm mới.");String selected=isAuto(text)?s.roomOptions.get(0).id():text.toUpperCase(Locale.ROOT);if(s.roomOptions.stream().noneMatch(r->r.id().equalsIgnoreCase(selected)))return answer(id,"Phòng '"+selected+"' không nằm trong danh sách còn trống. Hãy chọn một phòng bên dưới.",Step.ROOM,null,s.roomOptions);s.roomId=selected;s.step=Step.CONFIRM;return answer(id,summary(s)+"\nNhập 'xác nhận' để đặt phòng hoặc 'làm lại' để bắt đầu lại.",s.step,null);}
    case CONFIRM->{if(!isConfirm(text))return answer(id,"Mình chưa đặt phòng. Hãy nhập 'xác nhận' hoặc 'làm lại'.",s.step,null);List<AvailableRoom> latest=booking.availableRooms(s.start,s.end,s.attendees);if(latest.stream().noneMatch(r->r.id().equals(s.roomId))){s.roomId=null;return showAvailableRooms(id,s,"Phòng bạn chọn vừa không còn trống. Mình đã cập nhật danh sách, vui lòng chọn lại.");}ChatBookingResponse result=booking.book(new ChatBookingRequest(s.organizerId,s.title,null,s.start,s.end,s.attendees,s.roomId,s.participantIds,false,null));s.step=Step.DONE;return answer(id,result.message()+". Mã cuộc họp: "+result.meetingId()+".",s.step,result);}
    case DONE->{return answer(id,"Yêu cầu này đã hoàn tất. Nhập 'làm lại' để đặt một phòng khác.",s.step,null);}
  }throw bad("Trạng thái hội thoại không hợp lệ.");}
  private ChatMessageResponse showAvailableRooms(String id,State s,String prefix){s.roomOptions=booking.availableRooms(s.start,s.end,s.attendees);s.step=Step.ROOM;if(s.roomOptions.isEmpty())return answer(id,prefix+"\nHiện không có phòng nào đủ sức chứa và còn trống trong khung giờ này. Nhập 'làm lại' để chọn thời gian khác.",s.step,null,List.of());String list=s.roomOptions.stream().map(r->r.id()+" - "+r.name()+" ("+r.capacity()+" người, "+Objects.toString(r.location(),"chưa có vị trí")+")").reduce((a,b)->a+"\n"+b).orElse("");return answer(id,prefix+"\nCác phòng phù hợp:\n"+list+"\nHãy chọn một phòng hoặc nhập 'tự chọn' để hệ thống chọn phòng nhỏ nhất phù hợp.",s.step,null,s.roomOptions);}
  private void validateDraft(State s){if(s.start!=null&&!s.start.isAfter(OffsetDateTime.now()))throw bad("Thời gian bắt đầu phải ở tương lai.");if(s.start!=null&&s.end!=null&&!s.end.isAfter(s.start))throw bad("Thời gian kết thúc phải sau thời gian bắt đầu.");if(s.attendees<0)throw bad("Số người phải lớn hơn 0.");validateParticipants(s);}
  private void validateParticipants(State s){for(String userId:s.participantIds){UserDirectoryEntry u=users.findById(userId).orElseThrow(()->bad("Không tìm thấy người tham dự '"+userId+"'. Hãy nhập lại danh sách."));if(!"ACTIVE".equalsIgnoreCase(u.status))throw bad("Người tham dự '"+userId+"' đang bị vô hiệu hóa.");}}
  private static OffsetDateTime parseTime(String value){for(DateTimeFormatter f:List.of(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"),DateTimeFormatter.ISO_LOCAL_DATE_TIME)){try{return LocalDateTime.parse(value,f).atOffset(ZoneOffset.ofHours(7));}catch(DateTimeParseException ignored){}}try{return OffsetDateTime.parse(value);}catch(DateTimeParseException e){throw bad("Sai định dạng thời gian. Ví dụ đúng: 12/10/2026 14:00.");}}
  private static String summary(State s){return "Bạn muốn đặt phòng cho '"+s.title+"', từ "+s.start.format(DateTimeFormatter.ofPattern("HH:mm dd/MM/yyyy"))+" đến "+s.end.format(DateTimeFormatter.ofPattern("HH:mm dd/MM/yyyy"))+", "+s.attendees+" người, phòng "+(s.roomId==null?"do hệ thống tự chọn":s.roomId)+".";}
  private static boolean looksNatural(String s){return s.contains(" ")&&s.length()>20;}private static String blankToNull(String s){return s==null||s.isBlank()?null:s.trim();}private static boolean isReset(String s){return s.equalsIgnoreCase("làm lại")||s.equalsIgnoreCase("dat lai")||s.equalsIgnoreCase("reset");}private static boolean isSkip(String s){return s.equalsIgnoreCase("không")||s.equalsIgnoreCase("khong")||s.equalsIgnoreCase("bỏ qua");}private static boolean isAuto(String s){return s.equalsIgnoreCase("tự chọn")||s.equalsIgnoreCase("tu chon")||s.equalsIgnoreCase("auto");}private static boolean isConfirm(String s){return s.equalsIgnoreCase("xác nhận")||s.equalsIgnoreCase("xac nhan")||s.equalsIgnoreCase("đồng ý")||s.equalsIgnoreCase("dong y");}
  private static ChatMessageResponse answer(String id,String text,Step step,ChatBookingResponse booking){return answer(id,text,step,booking,List.of());}private static ChatMessageResponse answer(String id,String text,Step step,ChatBookingResponse booking,List<AvailableRoom> options){return new ChatMessageResponse(id,text,step.name(),booking,options);}private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}
}

@RestController @RequestMapping("/api") class ChatbotController{final ChatbotBookingService service;final ChatConversationService chat;final RoomRepository rooms;final MeetingRepository meetings;ChatbotController(ChatbotBookingService s,ChatConversationService c,RoomRepository r,MeetingRepository m){service=s;chat=c;rooms=r;meetings=m;}@PostMapping("/chatbot/message")ChatMessageResponse message(@Valid@RequestBody ChatMessageRequest q){return chat.reply(q);}@PostMapping("/chatbot/book-room")@ResponseStatus(HttpStatus.CREATED)ChatBookingResponse book(@Valid @RequestBody ChatBookingRequest q){return service.book(q);}@GetMapping("/rooms/available")List<AvailableRoom> available(@RequestParam OffsetDateTime startTime,@RequestParam OffsetDateTime endTime,@RequestParam @Min(1)int attendees){return service.availableRooms(startTime,endTime,attendees);}@GetMapping("/rooms")List<Room> rooms(){return rooms.findAll();}@GetMapping("/meetings")List<Meeting> meetings(){return meetings.findAll();}}
@org.springframework.context.annotation.Configuration
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="app.demo-data.enabled",havingValue="true",matchIfMissing=true)
class SeedData{
  @Bean ApplicationRunner seed(RoomRepository rooms,UserDirectoryRepository users,MeetingRepository meetings,ParticipantRepository participants){return args->{
    saveRoomIfMissing(rooms,new Room("ROOM-A","Phòng A",6,"Tầng 1"));
    saveRoomIfMissing(rooms,new Room("ROOM-B","Phòng B",12,"Tầng 2"));
    saveRoomIfMissing(rooms,new Room("ROOM-C","Phòng C",30,"Tầng 3"));
    saveRoomIfMissing(rooms,new Room("ROOM-D","Phòng họp trực tuyến",100,"Online"));
    saveUserIfMissing(users,"user-001","Nguyễn Văn An","an.nguyen@example.com","ACTIVE");
    saveUserIfMissing(users,"user-002","Trần Thị Bình","binh.tran@example.com","ACTIVE");
    saveUserIfMissing(users,"user-003","Lê Minh Châu","chau.le@example.com","ACTIVE");
    saveUserIfMissing(users,"user-004","Phạm Gia Dũng","dung.pham@example.com","ACTIVE");
    saveUserIfMissing(users,"user-locked","Tài khoản đã khóa","locked@example.com","INACTIVE");
    if(!meetings.existsById("DEMO-MEETING-001")){
      ZoneId zone=ZoneId.of("Asia/Ho_Chi_Minh");OffsetDateTime start=LocalDate.now(zone).plusDays(1).atTime(9,0).atZone(zone).toOffsetDateTime();
      Meeting meeting=new Meeting();meeting.id="DEMO-MEETING-001";meeting.organizerId="user-001";meeting.roomId="ROOM-A";meeting.title="Họp dự án mẫu";meeting.description="Dữ liệu ảo để kiểm tra phòng bị trùng lịch";meeting.startTime=start;meeting.endTime=start.plusHours(1);meeting.status=MeetingStatus.CONFIRMED;meetings.save(meeting);
      MeetingParticipant participant=new MeetingParticipant();participant.id="DEMO-PARTICIPANT-001";participant.meetingId=meeting.id;participant.userId="user-002";participant.fullName="Trần Thị Bình";participant.email="binh.tran@example.com";participant.status=ParticipantStatus.ACCEPTED;participants.save(participant);
    }
  };}
  private static void saveRoomIfMissing(RoomRepository repository,Room room){if(!repository.existsById(room.id))repository.save(room);}
  private static void saveUserIfMissing(UserDirectoryRepository repository,String id,String name,String email,String status){if(!repository.existsById(id)){UserDirectoryEntry user=new UserDirectoryEntry();user.id=id;user.fullName=name;user.email=email;user.status=status;repository.save(user);}}
}
